    public async Task<IReadOnlyList<AgentToolCatalogEntry>> ListToolCatalogAsync(
        AgentProfileRecord? profile = null,
        Guid? sessionId = null,
        AgentWorkspaceRecord? workspace = null,
        bool includeUnavailable = true,
        CancellationToken cancellationToken = default)
    {
        var effectiveProfile = profile;
        var (context, executionTarget) = await CreateSourceContextAsync(
                sessionId,
                effectiveProfile,
                workspace,
                cancellationToken)
            .ConfigureAwait(false);
        var catalog = new List<AgentToolCatalogEntry>();
        foreach (var candidate in await ListOwnedRuntimeToolCandidatesAsync(
                         context,
                         executionTarget,
                         cancellationToken,
                         omitUnavailableSources: true)
                     .ConfigureAwait(false))
        {
            var descriptor = candidate.RuntimeTool.Descriptor;
            AgentToolReadiness? readiness;
            try
            {
                readiness = await GetReadinessAsync(candidate, context, cancellationToken)
                    .ConfigureAwait(false);
            }
            catch (SunderRpcException exception) when (!cancellationToken.IsCancellationRequested
                && exception.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
            {
                continue;
            }
            readiness ??= new AgentToolReadiness(
                descriptor.ToolId,
                AgentToolReadinessStatus.Ready,
                "Ready.");

            if (!includeUnavailable && readiness.Status != AgentToolReadinessStatus.Ready)
            {
                continue;
            }

            catalog.Add(new AgentToolCatalogEntry(descriptor, readiness));
        }

        return catalog
            .OrderByDescending(item => item.Descriptor.Priority)
            .ThenBy(item => item.Descriptor.DisplayName, StringComparer.OrdinalIgnoreCase)
            .ThenBy(item => item.Descriptor.ToolId, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    public async Task<IReadOnlyList<AgentToolCatalogEntry>> ListInstalledLocalToolsAsync(CancellationToken cancellationToken = default)
    {
        var (context, executionTarget) = await CreateSourceContextAsync(
                sessionId: null,
                profile: null,
                workspace: null,
                cancellationToken)
            .ConfigureAwait(false);
        var catalog = new List<AgentToolCatalogEntry>();
        foreach (var candidate in await ListOwnedRuntimeToolCandidatesAsync(
                         context,
                         executionTarget,
                         cancellationToken,
                         omitUnavailableSources: true)
                     .ConfigureAwait(false))
        {
            catalog.AddRange(new[] { candidate.RuntimeTool.Descriptor }
                .Where(descriptor => descriptor.SelectionScope == AgentToolSelectionScope.Tool)
                .Select(descriptor => new AgentToolCatalogEntry(
                descriptor,
                new AgentToolReadiness(
                    descriptor.ToolId,
                    AgentToolReadinessStatus.Ready,
                    "Installed capability. Runtime readiness depends on the selected session workspace."))));
        }

        return catalog
            .GroupBy(item => item.Descriptor.ToolId, StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .OrderByDescending(item => item.Descriptor.Priority)
            .ThenBy(item => item.Descriptor.DisplayName, StringComparer.OrdinalIgnoreCase)
            .ThenBy(item => item.Descriptor.ToolId, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    public async Task<IReadOnlyList<AgentToolReadiness>> ListToolReadinessAsync(CancellationToken cancellationToken = default)
        => (await ListToolCatalogAsync(includeUnavailable: true, cancellationToken: cancellationToken))
            .Select(item => item.Readiness)
            .ToArray();

    public async Task<IReadOnlyList<AgentToolDescriptor>> ListReadyToolDescriptorsAsync(
        AgentProfileRecord? profile = null,
        Guid? sessionId = null,
        AgentWorkspaceRecord? workspace = null,
        CancellationToken cancellationToken = default)
    {
        var effectiveProfile = profile;
        return (await ListToolCatalogAsync(profile, sessionId, workspace, includeUnavailable: false, cancellationToken))
            .Where(item => IsAllowedForProfile(effectiveProfile, item.Descriptor))
            .Select(item => item.Descriptor)
            .ToArray();
    }

    public async Task<IReadOnlyList<AgentRuntimeTool>> ListReadyRuntimeToolsAsync(
        AgentProfileRecord? profile = null,
        Guid? sessionId = null,
        AgentWorkspaceRecord? workspace = null,
        CancellationToken cancellationToken = default)
        => (await ListReadyOwnedRuntimeToolsAsync(
                profile,
                sessionId,
                workspace,
                cancellationToken)
            .ConfigureAwait(false))
            .Select(static tool => tool.RuntimeTool)
            .ToArray();

    internal async Task<IReadOnlyList<AgentOwnedRuntimeTool>> ListReadyOwnedRuntimeToolsAsync(
        AgentProfileRecord? profile = null,
        Guid? sessionId = null,
        AgentWorkspaceRecord? workspace = null,
        CancellationToken cancellationToken = default)
    {
        var effectiveProfile = profile;
        var (context, executionTarget) = await CreateSourceContextAsync(
                sessionId,
                effectiveProfile,
                workspace,
                cancellationToken)
            .ConfigureAwait(false);
        var candidates = await ListOwnedRuntimeToolCandidatesAsync(context, executionTarget, cancellationToken)
            .ConfigureAwait(false);
        var tools = new List<AgentOwnedRuntimeTool>();
        foreach (var candidate in candidates
                     .GroupBy(static item => item.RuntimeTool.Descriptor.ToolId, StringComparer.OrdinalIgnoreCase)
                     .Where(static group => group.Count() == 1)
                     .Select(static group => group.Single()))
        {
            var descriptor = candidate.RuntimeTool.Descriptor;
            var readiness = await GetReadinessAsync(candidate, context, cancellationToken)
                .ConfigureAwait(false);
            readiness ??= new AgentToolReadiness(
                descriptor.ToolId,
                AgentToolReadinessStatus.Ready,
                "Ready.");
            if (readiness.Status != AgentToolReadinessStatus.Ready
                || !IsAllowedForProfile(effectiveProfile, descriptor))
            {
                continue;
            }

            tools.Add(new AgentOwnedRuntimeTool(
                candidate.RuntimeTool,
                candidate.Invocation.OwnerPackageId,
                candidate.Invocation));
        }

        return tools
            .OrderByDescending(item => item.RuntimeTool.Descriptor.Priority)
            .ThenBy(item => item.RuntimeTool.Descriptor.DisplayName, StringComparer.OrdinalIgnoreCase)
            .ThenBy(item => item.RuntimeTool.Descriptor.ToolId, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    internal async Task<AgentToolInvocationReference?> ResolvePreparedInvocationAsync(
        AgentToolDescriptor advertisedDescriptor,
        string ownerPackageId,
        string? executionTargetOwnerPackageId,
        AgentProfileRecord profile,
        Guid sessionId,
        AgentWorkspaceRecord workspace,
        string? executionTargetConfigurationGeneration,
        CancellationToken cancellationToken)
    {
        var (sourceContext, executionTarget) = await CreateSourceContextAsync(
                sessionId,
                profile,
                workspace,
                cancellationToken)
            .ConfigureAwait(false);
        var context = sourceContext with
        {
            ExecutionTargetConfigurationGeneration = executionTargetConfigurationGeneration,
        };
        var matches = (await ListOwnedRuntimeToolCandidatesAsync(context, executionTarget, cancellationToken)
                .ConfigureAwait(false))
            .Where(candidate => IsSameAdvertisedTool(advertisedDescriptor, candidate.RuntimeTool.Descriptor)
                                && string.Equals(
                                    ownerPackageId,
                                    candidate.Invocation.OwnerPackageId,
                                    StringComparison.Ordinal)
                                && string.Equals(
                                    executionTargetOwnerPackageId,
                                    candidate.Invocation.ExecutionTargetOwnerPackageId,
                                    StringComparison.Ordinal)
                                && IsAllowedForProfile(profile, candidate.RuntimeTool.Descriptor)
                                && IsInvocationAvailable(candidate.Invocation))
            .Take(2)
            .ToArray();
        return matches.Length == 1 ? matches[0].Invocation : null;
    }

    internal async Task<AgentToolResult> ExecuteAsync(
        string toolId,
        string argumentsJson,
        Guid? sessionId = null,
        string? profileId = null,
        AgentWorkspaceRecord? workspace = null,
        bool allowOutsideConfiguredScope = false,
        Guid? runId = null,
        long? runRevision = null,
        Guid? userTurnId = null,
        string? toolCallId = null,
        IReadOnlyList<string>? approvedResourceReferences = null,
        IReadOnlyList<AgentResourceClaim>? approvedResourceClaims = null,
        IReadOnlyList<string>? approvedResourceCapabilities = null,
        CancellationToken cancellationToken = default,
        AgentToolDescriptor? advertisedDescriptor = null,
        string? advertisedOwnerPackageId = null,
        AgentToolInvocationReference? advertisedInvocation = null,
        AgentWorkspaceBindingRecord? expectedExecutionBinding = null,
        string? expectedExecutionTargetConfigurationGeneration = null,
        bool enforceExpectedExecutionContext = false,
        Action? dispatchStarted = null)
    {
        var effectiveProfileId = string.IsNullOrWhiteSpace(profileId) ? null : profileId;
        var executionBinding = ResolveExecutionBinding(workspace);
        var executionTarget = await ResolveExecutionTargetAsync(executionBinding, advertisedInvocation, cancellationToken).ConfigureAwait(false);
        var dispatchObserved = 0;
        Action? observeDispatch = dispatchStarted is null
            ? null
            : () =>
            {
                dispatchStarted();
                Volatile.Write(ref dispatchObserved, 1);
            };
        if (!IsCurrentWorkspaceExecutionContext(
                workspace,
                enforceExpectedExecutionContext ? expectedExecutionBinding : executionBinding))
        {
            return PermissionContextChangedResult(toolId);
        }
        var context = new AgentToolExecutionContext(sessionId, effectiveProfileId, workspace, executionBinding, allowOutsideConfiguredScope, runId, runRevision, userTurnId, toolCallId)
        {
            TranscriptEpoch = ResolveTranscriptEpoch(sessionId),
            ApprovedResourceReferences = approvedResourceReferences ?? [],
            ApprovedResourceClaims = approvedResourceClaims ?? [],
            ApprovedResourceCapabilities = approvedResourceCapabilities ?? [],
            ExecutionTarget = executionTarget?.Reference,
            ExecutionTargetConfigurationGeneration = expectedExecutionTargetConfigurationGeneration,
            DispatchStarted = observeDispatch,
        };
        try
        {
            var resolvedTool = await ResolveAdvertisedToolAsync(
                toolId,
                context,
                advertisedDescriptor,
                advertisedOwnerPackageId,
                advertisedInvocation,
                executionTarget,
                cancellationToken);
            if (resolvedTool is null)
            {
                return new AgentToolResult(
                    toolId,
                    $"Tool '{toolId}' was not in the ready, assigned tool catalog for this run.",
                    Content: $"### Tool denied\n\nTool '{toolId}' was not advertised as ready and assigned for this run.",
                    IsError: true,
                    ErrorCode: AgentToolSecurityErrorCodes.NotAdvertised);
            }
            if (!await IsCurrentExecutionTargetConfigurationAsync(
                    context,
                    resolvedTool.Invocation,
                    cancellationToken).ConfigureAwait(false))
            {
                return PermissionContextChangedResult(toolId);
            }
            var executionContext = context with
            {
                ResourceOperation = CreateResourceOperation(
                    context,
                    resolvedTool.Invocation,
                    ResolveActionId(toolId),
                    canIssueOutsideAuthority: false),
            };
            var request = new AgentToolRequest(toolId, argumentsJson);
            await resolvedTool.Invocation.SourceProvider.EnsureCurrentAsync(cancellationToken).ConfigureAwait(false);
            if (resolvedTool.Invocation.ExecutionTargetProvider is { } target)
                await target.EnsureCurrentAsync(cancellationToken).ConfigureAwait(false);
            if (resolvedTool.Invocation.ObservedExecutionProvider is { } observed)
                await observed.EnsureCurrentAsync(cancellationToken).ConfigureAwait(false);
            return await StartWorkspaceBoundInvocation(
                workspace,
                enforceExpectedExecutionContext ? expectedExecutionBinding : executionBinding,
                PermissionContextChangedResult(toolId),
                () => ExecuteToolAsync(
                    resolvedTool.Invocation,
                    executionContext,
                    request,
                    cancellationToken)).ConfigureAwait(false);
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && (ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
            && Volatile.Read(ref dispatchObserved) != 0)
        {
            return ToolTransportOutcomeAmbiguousResult(toolId, ex.Message);
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            return PackageUnavailableResult(toolId, ex.Message);
        }
        catch (OperationCanceledException ex) when (
            !cancellationToken.IsCancellationRequested
            && Volatile.Read(ref dispatchObserved) != 0)
        {
            return ToolTransportOutcomeAmbiguousResult(toolId, ex.Message);
        }
        catch (OperationCanceledException ex) when (!cancellationToken.IsCancellationRequested)
        {
            return new AgentToolResult(
                toolId,
                $"Tool '{toolId}' timed out or was canceled before it completed: {ex.Message}",
                Content: $"### Tool execution failed\n\nTool '{toolId}' timed out or was canceled before it completed.\n\n{ex.Message}",
                IsError: true,
                ErrorCode: AgentToolResultErrorCodes.ToolExecutionException);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception ex) when (Volatile.Read(ref dispatchObserved) != 0)
        {
            return ToolTransportOutcomeAmbiguousResult(toolId, ex.Message);
        }
        catch (Exception ex)
        {
            return new AgentToolResult(
                toolId,
                $"Tool '{toolId}' failed: {ex.Message}",
                Content: $"### Tool execution failed\n\n{ex.Message}",
                IsError: true,
                ErrorCode: AgentToolResultErrorCodes.ToolExecutionException);
        }
    }

    private static AgentToolResult ToolTransportOutcomeAmbiguousResult(string toolId, string message)
        => new(
            toolId,
            $"Tool '{toolId}' was dispatched, but its worker connection ended before a definitive response was received.",
            Content: $"### Tool outcome is uncertain\n\nThe tool was dispatched, but its worker connection ended before a definitive response was received. Effects may have occurred. Verify current state before retrying.\n\n{message}",
            IsError: true,
            ErrorCode: AgentToolResultErrorCodes.ToolOutcomeAmbiguous);

    internal async Task<AgentToolResult?> PreflightExecutionAsync(
        string toolId,
        string argumentsJson,
        Guid? sessionId = null,
        string? profileId = null,
        AgentWorkspaceRecord? workspace = null,
        bool allowOutsideConfiguredScope = false,
        Guid? runId = null,
        long? runRevision = null,
        Guid? userTurnId = null,
        string? toolCallId = null,
        IReadOnlyList<string>? approvedResourceReferences = null,
        IReadOnlyList<AgentResourceClaim>? approvedResourceClaims = null,
        IReadOnlyList<string>? approvedResourceCapabilities = null,
        CancellationToken cancellationToken = default,
        AgentToolDescriptor? advertisedDescriptor = null,
        string? advertisedOwnerPackageId = null,
        AgentToolInvocationReference? advertisedInvocation = null,
        AgentWorkspaceBindingRecord? expectedExecutionBinding = null,
        string? expectedExecutionTargetConfigurationGeneration = null,
        bool enforceExpectedExecutionContext = false)
    {
        var effectiveProfileId = string.IsNullOrWhiteSpace(profileId) ? null : profileId;
        var executionBinding = ResolveExecutionBinding(workspace);
        var executionTarget = await ResolveExecutionTargetAsync(executionBinding, advertisedInvocation, cancellationToken).ConfigureAwait(false);
        if (!IsCurrentWorkspaceExecutionContext(
                workspace,
                enforceExpectedExecutionContext ? expectedExecutionBinding : executionBinding))
        {
            return PermissionContextChangedResult(toolId);
        }
        var context = new AgentToolExecutionContext(
            sessionId,
            effectiveProfileId,
            workspace,
            executionBinding,
            allowOutsideConfiguredScope,
            runId,
            runRevision,
            userTurnId,
            toolCallId)
        {
            TranscriptEpoch = ResolveTranscriptEpoch(sessionId),
            ApprovedResourceReferences = approvedResourceReferences ?? [],
            ApprovedResourceClaims = approvedResourceClaims ?? [],
            ApprovedResourceCapabilities = approvedResourceCapabilities ?? [],
            ExecutionTarget = executionTarget?.Reference,
            ExecutionTargetConfigurationGeneration = expectedExecutionTargetConfigurationGeneration,
        };
        ResolvedTool? resolvedTool;
        try
        {
            resolvedTool = await ResolveAdvertisedToolAsync(
                toolId,
                context,
                advertisedDescriptor,
                advertisedOwnerPackageId,
                advertisedInvocation,
                executionTarget,
                cancellationToken);
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            return PackageUnavailableResult(toolId, ex.Message);
        }
        if (resolvedTool is null)
        {
            return null;
        }
        try
        {
            if (!await IsCurrentExecutionTargetConfigurationAsync(
                    context,
                    resolvedTool.Invocation,
                    cancellationToken).ConfigureAwait(false))
            {
                return PermissionContextChangedResult(toolId);
            }
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            return PackageUnavailableResult(toolId, ex.Message);
        }
        catch (Exception) when (!cancellationToken.IsCancellationRequested)
        {
            return PermissionContextChangedResult(toolId);
        }
        AgentToolResult? result;
        try
        {
            var executionContext = context with
            {
                ResourceOperation = CreateResourceOperation(
                    context,
                    resolvedTool.Invocation,
                    ResolveActionId(toolId),
                    canIssueOutsideAuthority: false),
            };
            result = await StartWorkspaceBoundInvocation<AgentToolResult?>(
                workspace,
                enforceExpectedExecutionContext ? expectedExecutionBinding : executionBinding,
                PermissionContextChangedResult(toolId),
                () => resolvedTool.Invocation.SourceProvider.Service.PreflightAsync(
                    executionContext,
                    new AgentToolRequest(toolId, argumentsJson),
                    cancellationToken)).ConfigureAwait(false);
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            return PackageUnavailableResult(toolId, ex.Message);
        }
        if (result is null || result.IsError)
        {
            return result;
        }

        return new AgentToolResult(
            toolId,
            "Tool preflight returned an invalid non-error skip result.",
            Content: "### Tool not dispatched\n\nThe tool preflight did not return a valid failure result, so execution was skipped.",
            IsError: true,
            ErrorCode: AgentToolResultErrorCodes.ToolExecutionException);
    }

    public async Task<AgentPermissionRequest?> BuildPermissionRequestAsync(
        string toolId,
        string argumentsJson,
        Guid? sessionId = null,
        string? profileId = null,
        AgentWorkspaceRecord? workspace = null,
        Guid? runId = null,
        long? runRevision = null,
        Guid? userTurnId = null,
        string? toolCallId = null,
        CancellationToken cancellationToken = default,
        AgentToolDescriptor? advertisedDescriptor = null)
    {
        var resolution = await ResolvePermissionRequirementAsync(
            toolId,
            argumentsJson,
            sessionId,
            profileId,
            workspace,
            runId,
            runRevision,
            userTurnId,
            toolCallId,
            advertisedDescriptor: advertisedDescriptor,
            advertisedOwnerPackageId: null,
            cancellationToken: cancellationToken);
        if (resolution is null)
        {
            return CreateDeniedPermissionRequest(
                toolId,
                $"Tool '{toolId}' was not in the ready, assigned tool catalog for this run.");
        }

        return string.IsNullOrWhiteSpace(resolution.DeniedReason)
            ? resolution.PermissionRequest
            : CreateDeniedPermissionRequest(toolId, resolution.DeniedReason);
    }

    internal async Task<AgentToolPermissionResolution?> ResolvePermissionRequirementAsync(
        string toolId,
        string argumentsJson,
        Guid? sessionId,
        string? profileId,
        AgentWorkspaceRecord? workspace,
        Guid? runId,
        long? runRevision,
        Guid? userTurnId,
        string? toolCallId,
        AgentToolDescriptor? advertisedDescriptor,
        string? advertisedOwnerPackageId = null,
        AgentToolInvocationReference? advertisedInvocation = null,
        CancellationToken cancellationToken = default,
        bool issueOutsideResourceAuthority = true,
        AgentWorkspaceBindingRecord? expectedExecutionBinding = null,
        bool enforceExpectedExecutionContext = false,
        bool requireReadiness = true)
    {
        var effectiveProfileId = string.IsNullOrWhiteSpace(profileId) ? null : profileId;
        var executionBinding = ResolveExecutionBinding(workspace);
        var executionTarget = await ResolveExecutionTargetAsync(executionBinding, advertisedInvocation, cancellationToken).ConfigureAwait(false);
        var context = new AgentToolExecutionContext(
            sessionId,
            effectiveProfileId,
            workspace,
            executionBinding,
            RunId: runId,
            RunRevision: runRevision,
            UserTurnId: userTurnId,
            ToolCallId: toolCallId)
        {
            TranscriptEpoch = ResolveTranscriptEpoch(sessionId),
            ExecutionTarget = executionTarget?.Reference,
        };
        ResolvedTool? resolvedTool;
        try
        {
            resolvedTool = await ResolveAdvertisedToolAsync(
                toolId,
                context,
                advertisedDescriptor,
                advertisedOwnerPackageId,
                advertisedInvocation,
                executionTarget,
                cancellationToken,
                requireReadiness);
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            if (advertisedDescriptor is null || advertisedInvocation is null)
            {
                return null;
            }

            return new AgentToolPermissionResolution(
                advertisedDescriptor,
                PermissionRequest: null,
                executionBinding,
                advertisedInvocation.ExecutionTarget,
                advertisedInvocation.OwnerPackageId,
                ex.Message);
        }
        if (resolvedTool is null)
        {
            return null;
        }
        if (!IsCurrentWorkspaceExecutionContext(
                workspace,
                enforceExpectedExecutionContext ? expectedExecutionBinding : executionBinding))
        {
            return new AgentToolPermissionResolution(
                resolvedTool.Descriptor,
                PermissionRequest: null,
                executionBinding,
                resolvedTool.Invocation.ExecutionTarget,
                resolvedTool.Invocation.OwnerPackageId,
                "The workspace paths or execution binding changed before permission planning began.");
        }

        string? executionTargetConfigurationGeneration;
        try
        {
            executionTargetConfigurationGeneration = await GetExecutionTargetConfigurationGenerationAsync(
                context,
                resolvedTool.Invocation,
                cancellationToken).ConfigureAwait(false);
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            return new AgentToolPermissionResolution(
                resolvedTool.Descriptor,
                PermissionRequest: null,
                executionBinding,
                resolvedTool.Invocation.ExecutionTarget,
                resolvedTool.Invocation.OwnerPackageId,
                ex.Message);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            return new AgentToolPermissionResolution(
                resolvedTool.Descriptor,
                PermissionRequest: null,
                executionBinding,
                resolvedTool.Invocation.ExecutionTarget,
                resolvedTool.Invocation.OwnerPackageId,
                $"The execution-target configuration could not be captured safely: {ex.Message}");
        }

        context = context with
        {
            ExecutionTargetConfigurationGeneration = executionTargetConfigurationGeneration,
            ResourceOperation = CreateResourceOperation(
                context,
                resolvedTool.Invocation,
                actionId: string.Empty,
                canIssueOutsideAuthority: issueOutsideResourceAuthority),
        };

        AgentPermissionRequest? permissionRequest;
        try
        {
            permissionRequest = await resolvedTool.Invocation.SourceProvider.Service.PermissionAsync(
                context,
                new AgentToolRequest(toolId, argumentsJson),
                cancellationToken).ConfigureAwait(false);
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            return new AgentToolPermissionResolution(
                resolvedTool.Descriptor,
                PermissionRequest: null,
                executionBinding,
                resolvedTool.Invocation.ExecutionTarget,
                resolvedTool.Invocation.OwnerPackageId,
                ex.Message);
        }

        string? deniedReason = null;
        if (permissionRequest is null && !resolvedTool.Descriptor.IsReadOnly)
        {
            if (sessionId is null
                || runId is null
                || runRevision is null
                || string.IsNullOrWhiteSpace(toolCallId)
                || workspace is null
                || string.IsNullOrWhiteSpace(resolvedTool.Descriptor.SourceId))
            {
                deniedReason = $"Mutating tool '{toolId}' has no permission policy and the execution context is insufficient for a durable approval.";
            }
            else
            {
                permissionRequest = new AgentPermissionRequest(
                    AgentPermissionService.GenericMutationActionId,
                    AgentPermissionService.GenericMutationBoundaryId,
                    $"Allow mutating tool '{resolvedTool.Descriptor.DisplayName}' to run?",
                    ToolId: resolvedTool.Descriptor.ToolId,
                    WorkspaceId: workspace.WorkspaceId,
                    BindingId: executionBinding?.BindingId,
                    ResourceDisplayName: resolvedTool.Descriptor.DisplayName,
                    ResourceReference: $"{resolvedTool.Descriptor.SourceKind}:{resolvedTool.Descriptor.SourceId}:{resolvedTool.Descriptor.ToolId}",
                    IsMutation: true);
            }
        }

        if (permissionRequest is not null)
        {
            permissionRequest = permissionRequest with
            {
                ToolId = string.IsNullOrWhiteSpace(permissionRequest.ToolId)
                    ? resolvedTool.Descriptor.ToolId
                    : permissionRequest.ToolId,
                WorkspaceId = string.IsNullOrWhiteSpace(permissionRequest.WorkspaceId)
                    ? workspace?.WorkspaceId
                    : permissionRequest.WorkspaceId,
                BindingId = string.IsNullOrWhiteSpace(permissionRequest.BindingId)
                    ? executionBinding?.BindingId
                    : permissionRequest.BindingId,
                IsMutation = permissionRequest.IsMutation || !resolvedTool.Descriptor.IsReadOnly,
            };
        }

        string? currentExecutionTargetConfigurationGeneration;
        try
        {
            currentExecutionTargetConfigurationGeneration = await GetExecutionTargetConfigurationGenerationAsync(
                context,
                resolvedTool.Invocation,
                cancellationToken).ConfigureAwait(false);
        }
        catch (SunderRpcException ex) when (!cancellationToken.IsCancellationRequested
            && ex.Error.Kind is SunderRpcErrorKind.StaleEndpoint or SunderRpcErrorKind.Unavailable)
        {
            await ReleasePermissionRequestAuthorityAsync(permissionRequest, resolvedTool.Invocation).ConfigureAwait(false);
            return new AgentToolPermissionResolution(
                resolvedTool.Descriptor,
                PermissionRequest: null,
                executionBinding,
                resolvedTool.Invocation.ExecutionTarget,
                resolvedTool.Invocation.OwnerPackageId,
                ex.Message);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            await ReleasePermissionRequestAuthorityAsync(permissionRequest, resolvedTool.Invocation).ConfigureAwait(false);
            return new AgentToolPermissionResolution(
                resolvedTool.Descriptor,
                PermissionRequest: null,
                executionBinding,
                resolvedTool.Invocation.ExecutionTarget,
                resolvedTool.Invocation.OwnerPackageId,
                $"The execution-target configuration could not be revalidated safely: {ex.Message}");
        }
        if (!string.Equals(
                executionTargetConfigurationGeneration,
                currentExecutionTargetConfigurationGeneration,
                StringComparison.Ordinal))
        {
            await ReleasePermissionRequestAuthorityAsync(permissionRequest, resolvedTool.Invocation).ConfigureAwait(false);
            return new AgentToolPermissionResolution(
                resolvedTool.Descriptor,
                PermissionRequest: null,
                executionBinding,
                resolvedTool.Invocation.ExecutionTarget,
                resolvedTool.Invocation.OwnerPackageId,
                "The execution-target configuration changed during permission planning.");
        }

        if (!IsCurrentWorkspaceExecutionContext(
                workspace,
                enforceExpectedExecutionContext ? expectedExecutionBinding : executionBinding))
        {
            await ReleasePermissionRequestAuthorityAsync(permissionRequest, resolvedTool.Invocation).ConfigureAwait(false);
            return new AgentToolPermissionResolution(
                resolvedTool.Descriptor,
                PermissionRequest: null,
                executionBinding,
                resolvedTool.Invocation.ExecutionTarget,
                resolvedTool.Invocation.OwnerPackageId,
                "The workspace paths or execution binding changed during permission planning.");
        }

        return new AgentToolPermissionResolution(
            resolvedTool.Descriptor,
            permissionRequest,
            executionBinding,
            resolvedTool.Invocation.ExecutionTarget,
            resolvedTool.Invocation.OwnerPackageId,
            deniedReason)
        {
            ExecutionTargetConfigurationGeneration = executionTargetConfigurationGeneration,
        };
    }

}

using System.Diagnostics;
using Sunder.Package.Agent.Contracts.Models;
using Sunder.Package.Agent.Models;
using Sunder.Sdk.Logging;

namespace Sunder.Package.Agent.Services.BehaviorLoops;

internal sealed partial class AgentBehaviorLoopHost
{
    internal void RecordToolCallStart(AgentToolCallRequest toolCall)
    {
        SaveCheckpoint(AgentRunStatus.Running, $"Executing tool '{toolCall.ToolId}'.");

        LogEvent(PackageLogLevel.Information, "tool.execution.start", "Executing tool.", attributes: new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["tool.id"] = toolCall.ToolId,
        });
    }

    private async Task<AgentToolCallOutcome> RecordSecurityDenialAsync(
        AgentToolCallRequest toolCall,
        string summary,
        string errorCode,
        CancellationToken cancellationToken)
    {
        var result = new AgentToolResult(
            toolCall.ToolId,
            summary,
            Content: $"### Tool denied\n\n{summary}",
            IsError: true,
            ErrorCode: errorCode);
        await _toolService.ReleasePreparedInvocationAsync(GetToolExecution(toolCall.CallId).ExecutionId).ConfigureAwait(false);
        var resultTurn = CompleteToolExecution(
            toolCall,
            result,
            AgentToolExecutionStatus.Failed,
            errorCode);
        var checkpoint = SaveCheckpoint(AgentRunStatus.Failed, summary);
        await PublishLifecycleEventAsync(
            AgentLifecycleEventKind.RunFailed,
            AgentRunStatus.Failed,
            triggerTurn: resultTurn,
            checkpoint: checkpoint,
            cancellationToken: cancellationToken);
        return new AgentToolCallOutcome(AgentToolCallOutcomeKind.Denied, checkpoint, result);
    }

    private async Task<AgentToolCallOutcome> RecordApprovedSecurityDenialAsync(
        AgentPendingPermissionRequestRecord pending,
        string summary,
        string errorCode,
        CancellationToken cancellationToken)
    {
        var result = new AgentToolResult(
            pending.ToolId ?? string.Empty,
            summary,
            Content: $"### Approved tool not executed\n\n{summary}",
            IsError: true,
            ErrorCode: errorCode);
        if (pending.ToolExecutionId is { } executionId)
        {
            await _toolService.ReleasePreparedInvocationAsync(executionId).ConfigureAwait(false);
        }
        var resultTurn = CompleteToolExecution(
            pending,
            result,
            AgentToolExecutionStatus.Failed,
            errorCode,
            AgentPendingPermissionStatus.Expired);
        var checkpoint = SaveCheckpoint(AgentRunStatus.Failed, summary);
        await PublishLifecycleEventAsync(
            AgentLifecycleEventKind.RunFailed,
            AgentRunStatus.Failed,
            triggerTurn: resultTurn,
            checkpoint: checkpoint,
            cancellationToken: cancellationToken);
        return new AgentToolCallOutcome(AgentToolCallOutcomeKind.Denied, checkpoint, result);
    }

    internal async Task<IReadOnlyList<ExecutedToolResult>> ExecuteToolBatchAsync(
        IReadOnlyList<AgentToolCallRequest> batch,
        IReadOnlyDictionary<string, AgentToolDescriptor> availableToolsById,
        CancellationToken cancellationToken)
    {
        var inFlight = new Dictionary<string, Task<ResolvedToolResult>>(StringComparer.Ordinal);
        var tasks = batch.Select(call => ExecuteToolCallForBatchAsync(
            call,
            availableToolsById,
            inFlight,
            cancellationToken));
        return await Task.WhenAll(tasks);
    }

    private async Task<ExecutedToolResult> ExecuteToolCallForBatchAsync(
        AgentToolCallRequest toolCall,
        IReadOnlyDictionary<string, AgentToolDescriptor> availableToolsById,
        IDictionary<string, Task<ResolvedToolResult>> inFlight,
        CancellationToken cancellationToken)
    {
        var stopwatch = Stopwatch.StartNew();
        var resolved = await ResolveBatchToolResultAsync(toolCall, availableToolsById, inFlight, cancellationToken);
        return new ExecutedToolResult(
            toolCall,
            resolved.Result,
            stopwatch.ElapsedMilliseconds,
            resolved.WasReadOnlyCacheHit);
    }

    private async Task<ResolvedToolResult> ResolveBatchToolResultAsync(
        AgentToolCallRequest toolCall,
        IReadOnlyDictionary<string, AgentToolDescriptor> availableToolsById,
        IDictionary<string, Task<ResolvedToolResult>> inFlight,
        CancellationToken cancellationToken)
    {
        if (!IsCacheableReadOnlyTool(toolCall.ToolId, availableToolsById)
            || HasTransientResourceCapabilities(toolCall.CallId))
        {
            return await ResolveToolResultAsync(toolCall, availableToolsById, cancellationToken);
        }

        var key = BuildToolCallCacheKey(toolCall);
        if (!inFlight.TryGetValue(key, out var primaryTask))
        {
            primaryTask = ResolveToolResultAsync(toolCall, availableToolsById, cancellationToken);
            inFlight[key] = primaryTask;
            return await primaryTask;
        }

        var primary = await primaryTask;
        return primary.Result.IsError
            ? await ResolveToolResultAsync(toolCall, availableToolsById, cancellationToken)
            : new ResolvedToolResult(
                CreateDuplicateReadOnlyToolResult(toolCall.ToolId, primary.Result),
                WasReadOnlyCacheHit: true);
    }

    internal async Task<AgentToolCallOutcome> RecordExecutedToolResultAsync(
        ExecutedToolResult executed,
        CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (!IsCurrentRun())
        {
            throw new OperationCanceledException(cancellationToken);
        }

        var call = executed.ToolCall;
        var result = executed.Result;
        if (AgentToolSuspensionCompatibility.TryCreateChildJoin(call, result, _userTurnId, out var childJoin))
        {
            var suspended = _sessionService.SuspendRunAndCompleteToolExecution(
                _runLease,
                childJoin!,
                result.Summary,
                GetToolExecution(call.CallId).ExecutionId,
                result,
                "child-suspension-durable");
            return new AgentToolCallOutcome(AgentToolCallOutcomeKind.WaitingForApproval, suspended.Checkpoint, result);
        }

        if (string.Equals(result.ErrorCode, AgentToolResultErrorCodes.ChildWaitingForApproval, StringComparison.OrdinalIgnoreCase))
        {
            CompleteToolExecution(
                call,
                result,
                AgentToolExecutionStatus.Failed,
                AgentToolResultErrorCodes.ChildWaitingForApproval);
            var checkpoint = SaveCheckpoint(AgentRunStatus.Failed, "A waiting child task did not provide a durable child-session identity.");
            return new AgentToolCallOutcome(AgentToolCallOutcomeKind.Failed, checkpoint, result);
        }

        var executionStatus = string.Equals(
            result.ErrorCode,
            AgentToolResultErrorCodes.ToolOutcomeAmbiguous,
            StringComparison.Ordinal)
            ? AgentToolExecutionStatus.Ambiguous
            : result.IsError
                ? AgentToolExecutionStatus.Failed
                : AgentToolExecutionStatus.Completed;
        LogEvent(
            executionStatus == AgentToolExecutionStatus.Ambiguous
                ? PackageLogLevel.Warning
                : result.IsError ? PackageLogLevel.Error : PackageLogLevel.Information,
            executionStatus == AgentToolExecutionStatus.Ambiguous
                ? "tool.execution.ambiguous"
                : result.IsError ? "tool.execution.failed" : "tool.execution.completed",
            result.Summary,
            executed.ElapsedMilliseconds,
            new Dictionary<string, object?>(StringComparer.Ordinal)
            {
                ["tool.id"] = call.ToolId,
                ["tool.backend_id"] = result.BackendId,
                ["tool.was_truncated"] = result.WasTruncated,
                ["tool.is_error"] = result.IsError,
                ["tool.error_code"] = result.ErrorCode,
                ["tool.content_length"] = result.Content?.Length ?? 0,
            });
        var resultTurn = CompleteToolExecution(
            call,
            result,
            executionStatus,
            executed.WasReadOnlyCacheHit
                ? "read-only-cache-hit"
                : result.ErrorCode ?? (result.IsError ? "tool-failed" : "tool-completed"),
            executed.WasReadOnlyCacheHit);
        await PublishLifecycleEventAsync(
            AgentLifecycleEventKind.ToolResultRecorded,
            AgentRunStatus.Running,
            triggerTurn: resultTurn,
            cancellationToken: cancellationToken);
        SaveCheckpoint(
            AgentRunStatus.Running,
            executionStatus switch
            {
                AgentToolExecutionStatus.Ambiguous => $"Tool '{call.ToolId}' returned without a definitive outcome. Continuing provider execution.",
                AgentToolExecutionStatus.Failed => $"Tool '{call.ToolId}' returned an error result. Continuing provider execution.",
                _ => $"Tool '{call.ToolId}' completed. Continuing provider execution.",
            });
        return new AgentToolCallOutcome(AgentToolCallOutcomeKind.Executed, Result: result);
    }

    internal static bool RequiresTerminalRecordingLast(ExecutedToolResult executed)
        => string.Equals(executed.Result.ErrorCode, AgentToolResultErrorCodes.ChildWaitingForApproval, StringComparison.OrdinalIgnoreCase);

    internal static IReadOnlyList<IReadOnlyList<AgentToolCallRequest>> BuildToolExecutionBatches(
        IReadOnlyList<AgentToolCallRequest> calls,
        IReadOnlyDictionary<string, AgentToolDescriptor> availableToolsById)
    {
        var batches = new List<IReadOnlyList<AgentToolCallRequest>>();
        var parallel = new List<AgentToolCallRequest>();
        foreach (var call in calls)
        {
            var isParallelSafe = availableToolsById.TryGetValue(call.ToolId, out var descriptor)
                                 && descriptor.ConcurrencyMode == AgentToolConcurrencyMode.ParallelSafe;
            if (isParallelSafe)
            {
                parallel.Add(call);
                if (parallel.Count >= MaxParallelToolExecutions)
                {
                    batches.Add(parallel.ToArray());
                    parallel.Clear();
                }
                continue;
            }

            if (parallel.Count > 0)
            {
                batches.Add(parallel.ToArray());
                parallel.Clear();
            }
            batches.Add([call]);
        }

        if (parallel.Count > 0)
        {
            batches.Add(parallel.ToArray());
        }
        return batches;
    }

    private async Task<ResolvedToolResult> ResolveToolResultAsync(
        AgentToolCallRequest call,
        IReadOnlyDictionary<string, AgentToolDescriptor> availableToolsById,
        CancellationToken cancellationToken)
    {
        if (!_toolService.IsCurrentWorkspaceExecutionContext(_workspace, _executionBinding))
        {
            return new ResolvedToolResult(
                new AgentToolResult(
                    call.ToolId,
                    "The workspace execution context changed before the tool could run.",
                    Content: "### Tool not dispatched\n\nThe workspace paths or execution binding changed. Retry the tool against the current workspace configuration.",
                    IsError: true,
                    ErrorCode: AgentToolSecurityErrorCodes.PermissionContextChanged),
                WasReadOnlyCacheHit: false);
        }
        if (!IsCacheableReadOnlyTool(call.ToolId, availableToolsById)
            || HasTransientResourceCapabilities(call.CallId)
            || _executionTargetConfigurationGenerationByCallId.GetValueOrDefault(call.CallId) is not null)
        {
            try
            {
                return new ResolvedToolResult(
                    await ExecuteToolAsync(call, availableToolsById[call.ToolId], cancellationToken),
                    WasReadOnlyCacheHit: false);
            }
            finally
            {
                InvalidateReadOnlyToolResultCache();
            }
        }

        var key = BuildToolCallCacheKey(call);
        lock (_readOnlyToolResultCacheSync)
        {
            if (_readOnlyToolResultCache.TryGetValue(key, out var cached))
            {
                return new ResolvedToolResult(
                    CreateDuplicateReadOnlyToolResult(call.ToolId, cached),
                    WasReadOnlyCacheHit: true);
            }
        }

        var executed = await ExecuteToolAsync(call, availableToolsById[call.ToolId], cancellationToken);
        if (!executed.IsError && !executed.RequiresPromptContextRefresh)
        {
            lock (_readOnlyToolResultCacheSync)
            {
                _readOnlyToolResultCache[key] = executed;
            }
        }
        return new ResolvedToolResult(executed, WasReadOnlyCacheHit: false);
    }

    private async Task<AgentToolResult> ExecuteToolAsync(
        AgentToolCallRequest call,
        AgentToolDescriptor descriptor,
        CancellationToken cancellationToken)
    {
        var allowOutsideConfiguredScope = _allowOutsideConfiguredScopeByCallId.GetValueOrDefault(call.CallId);
        var approvedResourceReferences = _approvedResourceReferencesByCallId.GetValueOrDefault(call.CallId) ?? [];
        var approvedResourceClaims = _approvedResourceClaimsByCallId.GetValueOrDefault(call.CallId) ?? [];
        var approvedResourceCapabilities = _approvedResourceCapabilitiesByCallId.GetValueOrDefault(call.CallId) ?? [];
        var executionTargetConfigurationGeneration =
            _executionTargetConfigurationGenerationByCallId.GetValueOrDefault(call.CallId);
        var execution = GetToolExecution(call.CallId);
        var invocation = _toolService.GetPreparedInvocation(execution.ExecutionId)
            ?? throw new InvalidOperationException(
                $"Tool '{call.ToolId}' no longer has its prepared package invocation reference.");
        var preflight = await _toolService.PreflightExecutionAsync(
            call.ToolId,
            call.ArgumentsJson,
            _session.SessionId,
            _profile.ProfileId,
            _workspace,
            allowOutsideConfiguredScope,
            _runId,
            _runRevision,
            _userTurnId,
            call.CallId,
            approvedResourceReferences: approvedResourceReferences,
            approvedResourceClaims: approvedResourceClaims,
            approvedResourceCapabilities: approvedResourceCapabilities,
            cancellationToken: cancellationToken,
            advertisedDescriptor: descriptor,
            advertisedOwnerPackageId: execution.OwnerPackageId,
            advertisedInvocation: invocation,
            expectedExecutionBinding: _executionBinding,
            expectedExecutionTargetConfigurationGeneration: executionTargetConfigurationGeneration,
            enforceExpectedExecutionContext: true);
        if (preflight is not null)
        {
            await _toolService.ReleasePreparedInvocationAsync(execution.ExecutionId).ConfigureAwait(false);
            return preflight;
        }

        var recordDispatchStarted = CreateDispatchStartedCallback(execution);
        var executionTask = _toolService.ExecuteAsync(
            call.ToolId,
            call.ArgumentsJson,
            _session.SessionId,
            _profile.ProfileId,
            _workspace,
            allowOutsideConfiguredScope,
            runId: _runId,
            runRevision: _runRevision,
            userTurnId: _userTurnId,
            toolCallId: call.CallId,
            approvedResourceReferences: approvedResourceReferences,
            approvedResourceClaims: approvedResourceClaims,
            approvedResourceCapabilities: approvedResourceCapabilities,
            advertisedDescriptor: descriptor,
            advertisedOwnerPackageId: execution.OwnerPackageId,
            advertisedInvocation: invocation,
            expectedExecutionBinding: _executionBinding,
            expectedExecutionTargetConfigurationGeneration: executionTargetConfigurationGeneration,
            enforceExpectedExecutionContext: true,
            dispatchStarted: recordDispatchStarted,
            cancellationToken: cancellationToken);
        try
        {
            return await executionTask;
        }
        finally
        {
            await _toolService.ReleasePreparedInvocationAsync(execution.ExecutionId).ConfigureAwait(false);
        }
    }

    private Action CreateDispatchStartedCallback(AgentToolExecutionRecord execution)
    {
        var dispatchRecorded = 0;
        return () =>
        {
            if (Interlocked.Exchange(ref dispatchRecorded, 1) != 0)
            {
                return;
            }

            var started = _sessionService.StartToolExecution(
                _runLease,
                execution.ExecutionId,
                execution.InvocationFingerprint);
            _sessionService.PublishToolExecutionStarted(_runLease, started.ToolCallTurn);
        };
    }

    private async Task<AgentToolResult> ExecuteApprovedToolAsync(
        AgentPendingPermissionRequestRecord pending,
        AgentToolDescriptor advertisedDescriptor,
        string advertisedOwnerPackageId,
        AgentToolInvocationReference advertisedInvocation,
        IReadOnlyList<string> approvedResourceReferences,
        IReadOnlyList<AgentResourceClaim> approvedResourceClaims,
        IReadOnlyList<string> approvedResourceCapabilities,
        Action dispatchStarted,
        CancellationToken cancellationToken)
    {
        var allowOutsideConfiguredScope = string.Equals(
            pending.BoundaryId,
            AgentPermissionBoundaryIds.OutsideConfiguredScope,
            StringComparison.OrdinalIgnoreCase);
        try
        {
            return await _toolService.ExecuteAsync(
                pending.ToolId ?? string.Empty,
                pending.ArgumentsJson,
                pending.SessionId,
                _profile.ProfileId,
                _workspace,
                allowOutsideConfiguredScope: allowOutsideConfiguredScope,
                runId: pending.RunId,
                runRevision: pending.RunRevision,
                userTurnId: pending.UserTurnId,
                toolCallId: pending.CallId,
                approvedResourceReferences: approvedResourceReferences,
                approvedResourceClaims: approvedResourceClaims,
                approvedResourceCapabilities: approvedResourceCapabilities,
                advertisedDescriptor: advertisedDescriptor,
                advertisedOwnerPackageId: advertisedOwnerPackageId,
                advertisedInvocation: advertisedInvocation,
                expectedExecutionBinding: _executionBinding,
                expectedExecutionTargetConfigurationGeneration:
                    _executionTargetConfigurationGenerationByCallId.GetValueOrDefault(pending.CallId),
                enforceExpectedExecutionContext: true,
                dispatchStarted: dispatchStarted,
                cancellationToken: cancellationToken);
        }
        finally
        {
            if (!advertisedDescriptor.IsReadOnly)
            {
                InvalidateReadOnlyToolResultCache();
            }
            if (pending.ToolExecutionId is { } executionId)
            {
                await _toolService.ReleasePreparedInvocationAsync(executionId).ConfigureAwait(false);
            }
        }
    }

    private static bool IsCacheableReadOnlyTool(
        string toolId,
        IReadOnlyDictionary<string, AgentToolDescriptor> availableToolsById)
        => availableToolsById.TryGetValue(toolId, out var descriptor) && descriptor.IsReadOnly;

    private bool HasTransientResourceCapabilities(string callId)
        => _approvedResourceCapabilitiesByCallId.GetValueOrDefault(callId)?.Count > 0;

    private string BuildToolCallCacheKey(AgentToolCallRequest call)
        => string.Concat(
            call.ToolId,
            "\n",
            _allowOutsideConfiguredScopeByCallId.GetValueOrDefault(call.CallId) ? "outside-approved" : "configured-scope",
            "\n",
            _executionTargetConfigurationGenerationByCallId.GetValueOrDefault(call.CallId) ?? string.Empty,
            "\n",
            string.Join("\n", (_approvedResourceReferencesByCallId.GetValueOrDefault(call.CallId) ?? []).Order(StringComparer.Ordinal)),
            "\n",
            string.IsNullOrWhiteSpace(call.ArgumentsJson) ? "{}" : call.ArgumentsJson.Trim());

    private static AgentToolResult CreateDuplicateReadOnlyToolResult(string toolId, AgentToolResult cached)
        => new(
            toolId,
            $"Skipped duplicate read-only tool call for '{toolId}' and reused the existing result.",
            Content: string.IsNullOrWhiteSpace(cached.Content)
                ? $"### Duplicate read-only tool call skipped\n\nTool '{toolId}' was already executed with the same arguments earlier in this run. Reuse the earlier result instead of repeating the call."
                : $"### Duplicate read-only tool call skipped\n\nTool '{toolId}' was already executed with the same arguments earlier in this run. Reusing the earlier result below.\n\n{cached.Content}",
            StructuredPayloadJson: cached.StructuredPayloadJson,
            Sources: cached.Sources,
            WasTruncated: cached.WasTruncated,
            BackendId: cached.BackendId,
            PresentationPayloadJson: cached.PresentationPayloadJson)
        {
            RequiresPromptContextRefresh = cached.RequiresPromptContextRefresh,
        };

    internal void InvalidateReadOnlyToolResultCache()
    {
        lock (_readOnlyToolResultCacheSync)
        {
            _readOnlyToolResultCache.Clear();
        }
    }

    internal async ValueTask<AgentToolCallOutcome> RecordUnexecutedToolCallAsync(
        AgentToolCallRequest toolCall,
        string summary)
    {
        try
        {
            var result = new AgentToolResult(
                toolCall.ToolId,
                summary,
                Content: $"### Tool call canceled\n\n{summary}",
                IsError: true,
                ErrorCode: "tool-batch-canceled");
            await _toolService.ReleasePreparedInvocationAsync(GetToolExecution(toolCall.CallId).ExecutionId).ConfigureAwait(false);
            CompleteToolExecution(
                toolCall,
                result,
                AgentToolExecutionStatus.Failed,
                "tool-batch-canceled");
            return new AgentToolCallOutcome(AgentToolCallOutcomeKind.Executed, Result: result);
        }
        catch (AgentRunTranscriptWriteRejectedException)
        {
            return new AgentToolCallOutcome(AgentToolCallOutcomeKind.Failed);
        }
    }

    internal sealed record ExecutedToolResult(
        AgentToolCallRequest ToolCall,
        AgentToolResult Result,
        long ElapsedMilliseconds,
        bool WasReadOnlyCacheHit);

    private sealed record ResolvedToolResult(
        AgentToolResult Result,
        bool WasReadOnlyCacheHit);
}

